1	/**
2	 * Judge AI Dredd — shared server plumbing.
3	 *
4	 * This module holds everything both the hook container and the dashboard
5	 * container need at startup: CLI argument parsing, the console→file log
6	 * mirror, store/interceptor construction, request-body size caps,
7	 * session-id validation, path validation, hook-auth middleware, transcript
8	 * backfill, and the session-log shape builder used by the dashboard.
9	 *
10	 * Neither `server-hook.ts` nor `server-dashboard.ts` instantiates stores
11	 * directly — they import `tracker`, `apiKeys`, `interceptor` from here. The
12	 * dashboard container constructs all three too, even though it doesn't
13	 * call `interceptor.evaluate`, because the sessions listing reads
14	 * `interceptor.getLog()` for its per-session rendering.
15	 *
16	 * All module-level side effects (logger wiring, `[STORE]` / `[AUTH]`
17	 * startup prints) happen here exactly once per process.
18	 */
19	
20	import { type IncomingMessage, type ServerResponse } from "node:http";
21	import { parseArgs } from "node:util";
22	import {
23	  createWriteStream,
24	  existsSync,
25	  mkdirSync,
26	  readFileSync,
27	  realpathSync,
28	  renameSync,
29	  statSync,
30	} from "node:fs";
31	import { join, sep } from "node:path";
32	import { inspect } from "node:util";
33	
34	// ============================================================================
35	// .env.local loader (local dev only)
36	// ============================================================================
37	//
38	// On the sandbox/Fargate deployment, secrets come from SSM via the task
39	// definition's `secrets` map — the env vars are already populated when this
40	// process starts. For local development we'd rather not require `export
41	// CLERK_SECRET_KEY=…` before every `npm run server`, so this block looks
42	// for `.env.local` in the project root and parses it into process.env.
43	//
44	// Behaviour:
45	//   - File missing → silent no-op.
46	//   - Key already set in process.env → not overwritten. The shell's
47	//     environment always wins so a one-off override stays a one-off.
48	//   - Lines starting with # are comments. Empty lines are skipped.
49	//   - Values may be quoted with single or double quotes; quotes are
50	//     stripped. No interpolation, no `export` prefix support — keep it
51	//     simple. If the format isn't enough, source the file from your
52	//     shell instead.
53	//
54	// `.env.local` is gitignored. NEVER commit secrets.
55	(() => {
56	  // Resolve relative to this source file so it works whether run from the
57	  // repo root or a different cwd (e.g. tsx invoked from /tmp).
58	  const candidates = [
59	    new URL("../.env.local", import.meta.url),
60	    new URL("../../.env.local", import.meta.url),
61	  ];
62	  for (const url of candidates) {
63	    let raw: string;
64	    try {
65	      raw = readFileSync(url, "utf8");
66	    } catch {
67	      continue;
68	    }
69	    for (const line of raw.split(/\r?\n/)) {
70	      const trimmed = line.trim();
71	      if (!trimmed || trimmed.startsWith("#")) continue;
72	      const eq = trimmed.indexOf("=");
73	      if (eq < 0) continue;
74	      const key = trimmed.slice(0, eq).trim();
75	      let value = trimmed.slice(eq + 1).trim();
76	      if (
77	        (value.startsWith('"') && value.endsWith('"')) ||
78	        (value.startsWith("'") && value.endsWith("'"))
79	      ) {
80	        value = value.slice(1, -1);
81	      }
82	      if (key && process.env[key] === undefined) {
83	        process.env[key] = value;
84	      }
85	    }
86	    break;
87	  }
88	})();
89	import { InMemorySessionStore } from "./session-tracker.js";
90	import { DynamoSessionStore } from "./dynamo-session-store.js";
91	import { CachedSessionStore } from "./cached-session-store.js";
92	import type { SessionStore, ImageBlock } from "./session-store.js";
93	import {
94	  type ApiKeyStore,
95	  InMemoryApiKeyStore,
96	} from "./api-key-store.js";
97	import { DynamoApiKeyStore } from "./dynamo-api-key-store.js";
98	import { CachedApiKeyStore } from "./cached-api-key-store.js";
99	import { PreToolInterceptor } from "./pretool-interceptor.js";
100	import type { PromptVariant } from "./intent-judge.js";
101	
102	export type TrustMode = "interactive" | "autonomous" | "learn";
103	
104	// ============================================================================
105	// CLI parsing + CONFIG
106	// ============================================================================
107	
108	const { values } = parseArgs({
109	  options: {
110	    port: { type: "string", default: "3001" },
111	    mode: { type: "string", default: "autonomous" },
112	    "judge-model": { type: "string", default: "nemotron-3-super" },
113	    backend: { type: "string", default: "ollama" },
114	    "embedding-model": { type: "string", default: "eu.cohere.embed-v4:0" },
115	    "hardened": { type: "boolean", default: false },
116	    "prompt": { type: "string", default: "" },
117	    "judge-effort": { type: "string", default: "" },
118	    "review-threshold": { type: "string", default: "0.6" },
119	    "deny-threshold": { type: "string", default: "0.15" },
120	    "hijack-threshold": { type: "string", default: "2" },
121	    "log-dir": { type: "string", default: "./results" },
122	    "console-log-dir": { type: "string", default: "./logs" },
123	  },
124	});
125	
126	// File logger — mirrors all console output to dredd-YYYY-MM-DD.log.
127	//
128	// Why this isn't appendFileSync: every console.* call would block the
129	// Node event loop while EFS round-trips the write (20-50ms p99 cold).
130	// Hot paths log on every hook event, so the cumulative cost was real.
131	//
132	// Replaced with an in-process queue + a single fs.WriteStream-backed
133	// drainer running on the next tick. Public API stays the same — the
134	// console overrides below call enqueueLogLine() and return immediately;
135	// the line eventually lands on disk asynchronously.
136	//
137	// Backpressure: drops newest writes once the queue exceeds the cap
138	// (default 10k lines). Hitting that cap means EFS is so slow we'd
139	// rather lose recent log lines than OOM the container. Drops are
140	// counted and surfaced once per minute via stderr so operators can see.
141	//
142	// Rotation: rolls over when the date changes (UTC midnight) OR the
143	// current file exceeds MAX_FILE_BYTES. The rolled file is renamed to
144	// dredd-YYYY-MM-DD.<seq>.log so the active filename always sorts last
145	// for the day.
146	//
147	// Shutdown: SIGTERM in main() awaits flushLogs() before exiting so
148	// in-flight log lines reach disk.
149	const LOG_DIR = values["console-log-dir"]!;
150	try { mkdirSync(LOG_DIR, { recursive: true }); } catch {}
151	
152	const MAX_QUEUE_LINES = 10_000;
153	const MAX_FILE_BYTES = 100 * 1024 * 1024; // 100 MB before forced rotation
154	const DROP_REPORT_INTERVAL_MS = 60_000;
155	
156	let logQueue: string[] = [];
157	let logStream: ReturnType<typeof createWriteStream> | null = null;
158	let logStreamPath: string | null = null;
159	let logStreamBytes = 0;
160	let logDraining = false;
161	let droppedLines = 0;
162	let lastDropReport = 0;
163	
164	function currentLogPath(): string {
165	  // Date in UTC so all containers in the fleet roll at the same instant.
166	  const date = new Date().toISOString().slice(0, 10);
167	  return join(LOG_DIR, `dredd-${date}.log`);
168	}
169	
170	function ensureStream(): void {
171	  const desired = currentLogPath();
172	  // Date changed (midnight UTC) — rotate by closing and reopening.
173	  if (logStream && logStreamPath !== desired) {
174	    try { logStream.end(); } catch {}
175	    logStream = null;
176	    logStreamPath = null;
177	    logStreamBytes = 0;
178	  }
179	  // Size exceeded — rotate to dredd-YYYY-MM-DD.<n>.log so the active
180	  // file remains dredd-YYYY-MM-DD.log.
181	  if (logStream && logStreamBytes >= MAX_FILE_BYTES && logStreamPath) {
182	    try { logStream.end(); } catch {}
183	    let n = 1;
184	    while (existsSync(`${logStreamPath}.${n}`)) n++;
185	    try { renameSync(logStreamPath, `${logStreamPath}.${n}`); } catch {}
186	    logStream = null;
187	    logStreamBytes = 0;
188	  }
189	  if (!logStream) {
190	    logStream = createWriteStream(desired, { flags: "a" });
191	    logStream.on("error", () => {
192	      // Silently abandon a broken stream so future writes can re-open
193	      // on the next ensureStream tick. Crashing the logger must never
194	      // crash the process.
195	      logStream = null;
196	      logStreamPath = null;
197	      logStreamBytes = 0;
198	    });
199	    logStreamPath = desired;
200	    // Best-effort starting size for rotation accounting.
201	    try { logStreamBytes = statSync(desired).size; } catch { logStreamBytes = 0; }
202	  }
203	}
204	
205	function reportDropsIfNeeded(): void {
206	  if (droppedLines === 0) return;
207	  const now = Date.now();
208	  if (now - lastDropReport < DROP_REPORT_INTERVAL_MS) return;
209	  // Use process.stderr.write directly so we don't recurse through the
210	  // console override.
211	  process.stderr.write(`[logger] dropped ${droppedLines} log lines (queue full)\n`);
212	  droppedLines = 0;
213	  lastDropReport = now;
214	}
215	
216	function drainLogs(): void {
217	  if (logDraining || logQueue.length === 0) return;
218	  logDraining = true;
219	  // setImmediate so we don't recurse inside the console override and so
220	  // multiple synchronous console calls coalesce into one drain.
221	  setImmediate(() => {
222	    try {
223	      ensureStream();
224	      if (!logStream) {
225	        logQueue.length = 0;
226	        return;
227	      }
228	      const batch = logQueue;
229	      logQueue = [];
230	      const payload = batch.join("");
231	      logStreamBytes += Buffer.byteLength(payload, "utf8");
232	      logStream.write(payload);
233	    } finally {
234	      logDraining = false;
235	      reportDropsIfNeeded();
236	      // If more arrived while we were draining, keep going.
237	      if (logQueue.length > 0) drainLogs();
238	    }
239	  });
240	}
241	
242	function enqueueLogLine(line: string): void {
243	  if (logQueue.length >= MAX_QUEUE_LINES) {
244	    droppedLines++;
245	    return;
246	  }
247	  logQueue.push(line);
248	  if (!logDraining) drainLogs();
249	}
250	
251	/**
252	 * Flush pending log lines and close the stream. Awaited on SIGTERM so
253	 * in-flight logs reach disk before the process exits. Bounded by a 5s
254	 * timeout — if the stream is wedged, exit anyway.
255	 */
256	export async function flushLogs(): Promise<void> {
257	  if (logQueue.length === 0 && !logStream) return;
258	  // Force one final drain.
259	  drainLogs();
260	  // Wait for the queue to empty.
261	  const start = Date.now();
262	  while (logQueue.length > 0 && Date.now() - start < 5_000) {
263	    await new Promise((r) => setTimeout(r, 50));
264	  }
265	  // Close the stream and wait for the close event.
266	  if (logStream) {
267	    const stream = logStream;
268	    logStream = null;
269	    await new Promise<void>((resolve) => {
270	      const done = () => resolve();
271	      stream.once("close", done);
272	      stream.once("error", done);
273	      stream.end();
274	      // Hard cap in case end() never fires.
275	      setTimeout(done, 2_000);
276	    });
277	  }
278	}
279	
280	// Prepend ISO timestamp to every console line so server logs are grep/sortable,
281	// and also write to the daily log file (asynchronously, see above).
282	for (const level of ["log", "info", "warn", "error"] as const) {
283	  const original = console[level].bind(console);
284	  console[level] = (...args: unknown[]) => {
285	    const timestamp = `[${new Date().toISOString()}]`;
286	    original(timestamp, ...args);
287	    const parts = args.map(a => typeof a === "string" ? a : inspect(a, { depth: 4, breakLength: Infinity }));
288	    enqueueLogLine(`${timestamp} ${parts.join(" ")}\n`);
289	  };
290	}
