292	export const PORT = parseInt(values.port!, 10);
293	
294	export const CONFIG = {
295	  mode: (values.mode as TrustMode) ?? "autonomous",
296	  judgeModel: values["judge-model"]!,
297	  judgeBackend: (values.backend as "ollama" | "bedrock")!,
298	  embeddingModel: values["embedding-model"]!,
299	  hardened: ((): PromptVariant | false => {
300	    const p = (values.prompt as string).trim();
301	    if (p === "B7" || p === "B7.1" || p === "B7.1-office") return p;
302	    if (p === "standard" || p === "") return values.hardened ? "B7.1" : false;
303	    throw new Error(`Unknown --prompt variant "${p}" (want: standard, B7, B7.1, B7.1-office)`);
304	  })(),
305	  judgeEffort: (values["judge-effort"] as string).trim() || undefined,
306	  reviewThreshold: parseFloat(values["review-threshold"]!),
307	  denyThreshold: parseFloat(values["deny-threshold"]!),
308	  hijackThreshold: Math.max(1, parseInt(values["hijack-threshold"]!, 10) || 2),
309	  logDir: values["log-dir"]!,
