362	
363	console.log(
364	  `  [STORE] Backend: ${STORE_BACKEND}` +
365	    (STORE_BACKEND === "dynamo"
366	      ? ` (table=${DYNAMO_TABLE_NAME}, region=${DYNAMO_REGION})`
367	      : ""),
368	);
369	
