389	export const interceptor = new PreToolInterceptor({
390	  judgeModel: CONFIG.judgeModel,
391	  judgeBackend: CONFIG.judgeBackend,
392	  embeddingModel: CONFIG.embeddingModel,
393	  reviewThreshold: CONFIG.reviewThreshold,
