399	/** Sessions whose goal has been registered with the interceptor.
400	 *  Hook container populates; dashboard container imports it to render
401	 *  interceptor log entries (getLog) on session detail views. */
402	export const registeredSessions = new Set<string>();
403	
404	// ============================================================================
405	// readBody + body caps
406	// ============================================================================
407	
408	export const BODY_LIMIT_DEFAULT = 1 * 1024 * 1024;       // 1 MB
409	export const BODY_LIMIT_TRANSCRIPT = 20 * 1024 * 1024;   // 20 MB
410	
411	export class BodyTooLargeError extends Error {
412	  readonly bodyLimit: number;
413	  constructor(limit: number) {
414	    super(`Request body exceeded ${limit} bytes`);
415	    this.name = "BodyTooLargeError";
416	    this.bodyLimit = limit;
417	  }
418	}
419	
420	export async function readBody(req: IncomingMessage, maxBytes = BODY_LIMIT_DEFAULT): Promise<string> {
421	  const declared = req.headers["content-length"];
422	  if (declared) {
423	    const n = parseInt(declared, 10);
424	    if (!Number.isNaN(n) && n > maxBytes) throw new BodyTooLargeError(maxBytes);
425	  }
426	  const chunks: Buffer[] = [];
427	  let total = 0;
428	  for await (const chunk of req) {
429	    const buf = chunk as Buffer;
430	    total += buf.length;
431	    if (total > maxBytes) {
432	      req.destroy();
433	      throw new BodyTooLargeError(maxBytes);
434	    }
435	    chunks.push(buf);
436	  }
437	  return Buffer.concat(chunks).toString("utf8");
438	}
439	
440	export function json(res: ServerResponse, status: number, data: unknown): void {
441	  res.writeHead(status, { "Content-Type": "application/json" });
442	  res.end(JSON.stringify(data));
443	}
444	
445	// ============================================================================
446	// session_id validation
447	// ============================================================================
448	
449	export const SESSION_ID_PATTERN = /^[A-Za-z0-9._-]{1,128}$/;
450	
451	export function isValidSessionId(v: unknown): v is string {
452	  return typeof v === "string" && SESSION_ID_PATTERN.test(v);
453	}
454	
455	export function rejectInvalidSessionId(res: ServerResponse, sessionId: unknown): sessionId is never {
456	  if (isValidSessionId(sessionId)) return false;
457	  json(res, 400, {
458	    error: "Invalid session_id",
459	    detail: `Must match ${SESSION_ID_PATTERN} (alphanumeric, dot, dash, underscore; 1–128 chars)`,
460	  });
461	  return true;
462	}
463	
464	// ============================================================================
465	// Filesystem path validation
466	// ============================================================================
467	
468	const ALLOW_ANY_PATH = process.env.DREDD_ALLOW_ANY_PATH === "1";
469	
470	export function isSafeServerReadablePath(p: unknown): p is string {
471	  if (ALLOW_ANY_PATH) return typeof p === "string";
472	  if (typeof p !== "string" || p.length === 0 || p.length > 4096) return false;
473	  if (p.includes("\0")) return false;
474	  let resolved: string;
475	  try {
476	    resolved = realpathSync(p);
477	  } catch {
478	    return false;
479	  }
480	  const marker = `${sep}.claude${sep}`;
481	  const normalised = resolved.endsWith(sep) ? resolved : resolved + sep;
482	  return normalised.includes(marker);
483	}
484	
485	export function safeServerReadablePath(p: unknown): string | null {
486	  return isSafeServerReadablePath(p) ? p : null;
487	}
488	
489	// ============================================================================
490	// Hook authentication
491	// ============================================================================
492	
493	type AuthMode = "off" | "optional" | "required";
494	export const AUTH_MODE: AuthMode = ((process.env.DREDD_AUTH_MODE ?? "optional") as AuthMode);
495	if (AUTH_MODE !== "off" && AUTH_MODE !== "optional" && AUTH_MODE !== "required") {
496	  throw new Error(
497	    `Invalid DREDD_AUTH_MODE=${process.env.DREDD_AUTH_MODE} — expected off|optional|required`,
498	  );
499	}
500	console.log(`  [AUTH]  Mode: ${AUTH_MODE}`);
501	
502	export interface RequestIdentity {
503	  ownerSub: string | null;
504	  ownerEmail: string | null;
505	  keyType: "user" | "service" | "benchmark" | null;
506	  keyPresented: boolean;
507	  keyValid: boolean;
508	}
509	
510	const ANON: RequestIdentity = { ownerSub: null, ownerEmail: null, keyType: null, keyPresented: false, keyValid: false };
511	
512	function extractBearer(req: IncomingMessage): string | null {
513	  const h = req.headers.authorization;
514	  if (typeof h !== "string") return null;
515	  const m = /^\s*Bearer\s+(\S+)\s*$/i.exec(h);
516	  return m ? m[1] : null;
517	}
518	
519	export async function authenticateHookRequest(
520	  req: IncomingMessage,
521	  res: ServerResponse,
522	): Promise<RequestIdentity | null> {
523	  if (AUTH_MODE === "off") return ANON;
524	
525	  const token = extractBearer(req);
526	  if (!token) {
527	    if (AUTH_MODE === "required") {
528	      json(res, 401, {
529	        error: "Missing API key",
530	        detail: "Send Authorization: Bearer <jaid_live_...>. " +
531	                "Generate one from the dashboard Settings → API Keys.",
532	      });
533	      return null;
534	    }
535	    return { ...ANON };
536	  }
537	
538	  const validated = await apiKeys.validateKey(token).catch((err) => {
539	    console.error(`[AUTH] validateKey error: ${err instanceof Error ? err.message : err}`);
540	    return null;
541	  });
542	
543	  if (!validated) {
544	    if (AUTH_MODE === "required") {
545	      json(res, 401, {
546	        error: "Invalid or revoked API key",
547	        detail: "Key does not match the expected format or has been revoked. " +
548	                "Generate a new one from the dashboard.",
549	      });
550	      return null;
551	    }
552	    return { ownerSub: null, ownerEmail: null, keyType: null, keyPresented: true, keyValid: false };
553	  }
554	
555	  return {
556	    ownerSub: validated.ownerSub,
557	    ownerEmail: validated.ownerEmail,
558	    keyType: validated.keyType,
559	    keyPresented: true,
560	    keyValid: true,
561	  };
562	}
563	
564	export function authStageForFeed(identity: RequestIdentity): string | null {
565	  if (!identity.keyPresented) return "unauthenticated";
566	  if (!identity.keyValid) return "bad-key";
567	  return null;
568	}
