570	// ============================================================================
571	// Misc helpers
572	// ============================================================================
573	
574	/** Derive the caller-visible origin behind an ALB / reverse proxy. */
575	export function resolvePublicOrigin(req: IncomingMessage): string {
576	  const xfProto = (req.headers["x-forwarded-proto"] as string | undefined)?.split(",")[0]?.trim();
577	  const xfHost = (req.headers["x-forwarded-host"] as string | undefined)?.split(",")[0]?.trim();
578	  const host = xfHost || req.headers.host || `localhost:${PORT}`;
579	  const proto = xfProto || (host.startsWith("localhost") ? "http" : "https");
580	  return `${proto}://${host}`;
581	}
582	
583	// ============================================================================
584	// Transcript backfill (hook-side only; exported for server-hook.ts)
585	// ============================================================================
586	
587	export function isConfirmationPrompt(text: string): boolean {
588	  return (
589	    /^\s*(yes|yeah|yep|ok|okay|sure|do it|go ahead|go|proceed|continue|y|k|confirm|approved?|lgtm|ship it|sounds good|that's right|correct|exactly|please|thanks|thank you|option\s+\w+|👍)\b/i.test(text)
590	    && text.trim().length < 80
591	  );
592	}
593	
594	export function extractImagesFromContentBlocks(blocks: any[]): ImageBlock[] {
595	  const images: ImageBlock[] = [];
596	  for (const b of blocks) {
597	    if (b.type === "image" && b.source?.type === "base64" && b.source?.data) {
598	      images.push({
599	        data: b.source.data,
600	        mediaType: b.source.media_type ?? "image/png",
601	      });
602	    }
603	  }
604	  return images;
605	}
606	
607	export function extractTextAndImages(content: unknown): { text: string; images: ImageBlock[] } {
608	  if (typeof content === "string") {
609	    return { text: content, images: [] };
610	  }
611	  if (Array.isArray(content)) {
612	    const text = content
613	      .filter((b: any) => b && b.type === "text" && typeof b.text === "string")
614	      .map((b: any) => b.text)
615	      .join("\n");
616	    return { text, images: extractImagesFromContentBlocks(content) };
617	  }
618	  return { text: "", images: [] };
619	}
620	
621	export function isSyntheticUserEntry(msg: any, text: string): boolean {
622	  if (msg?.isMeta === true) return true;
623	  const t = text.trim();
624	  if (!t) return false;
625	  return (
626	    t.startsWith("<command-name>") ||
627	    t.startsWith("<local-command-") ||
628	    t.startsWith("<command-message>") ||
629	    t.startsWith("<command-args>")
630	  );
631	}
632	
633	export function extractLastUserAndPriorAssistant(
634	  transcriptPathOrContent: string,
635	  isContent = false
636	): { lastUser: string | null; priorAssistant: string | null; images: ImageBlock[] } {
637	  let raw: string;
638	  if (isContent) {
639	    raw = transcriptPathOrContent;
640	  } else {
641	    const safe = safeServerReadablePath(transcriptPathOrContent);
642	    if (!safe) {
643	      return { lastUser: null, priorAssistant: null, images: [] };
644	    }
645	    try {
646	      raw = readFileSync(safe, "utf8");
647	    } catch {
648	      return { lastUser: null, priorAssistant: null, images: [] };
649	    }
650	  }
651	  try {
652	    const lines = raw.trim().split("\n").filter(Boolean);
653	    const userTurns: { user: string; prior: string | null; images: ImageBlock[] }[] = [];
654	    let pendingAssistant: string | null = null;
655	
656	    for (const line of lines) {
657	      try {
658	        const msg = JSON.parse(line);
659	        if (msg.type === "assistant") {
660	          const { text } = extractTextAndImages(msg.message?.content);
661	          const trimmed = text.trim();
662	          if (trimmed) pendingAssistant = trimmed;
663	        } else if (msg.type === "user") {
664	          const { text, images: imgs } = extractTextAndImages(msg.message?.content);
665	          const trimmed = text.trim();
666	          if (isSyntheticUserEntry(msg, trimmed)) continue;
667	          if (trimmed || imgs.length) {
668	            userTurns.push({ user: trimmed, prior: pendingAssistant, images: imgs });
669	          }
670	        }
671	      } catch {}
672	    }
673	
674	    if (userTurns.length === 0) return { lastUser: null, priorAssistant: null, images: [] };
675	
676	    for (let i = userTurns.length - 1; i >= 0; i--) {
677	      if (!isConfirmationPrompt(userTurns[i].user)) {
678	        return { lastUser: userTurns[i].user, priorAssistant: userTurns[i].prior, images: userTurns[i].images };
679	      }
680	    }
681	    const last = userTurns[userTurns.length - 1];
682	    return { lastUser: last.user, priorAssistant: last.prior, images: last.images };
683	  } catch {
684	    return { lastUser: null, priorAssistant: null, images: [] };
685	  }
686	}
687	
688	/**
689	 * Tag names we use to fence trusted vs untrusted content in the judge
690	 * prompt. If any of these appear in caller-supplied text (assistant or
691	 * user) they are stripped before reaching the prompt — otherwise an
692	 * attacker could close the tag, inject directives in what the model
693	 * sees as the system context, and reopen.
694	 *
695	 * Keep this list in sync with the tags actually used in
696	 *   - this file's buildContextualIntent (<prior_assistant_response>, <user_prompt>)
697	 *   - intent-judge.ts evaluate() (<user_intent>, <actions>, <action>)
698	 */
699	const FENCE_TAG_NAMES = [
700	  "user_intent",
701	  "user_prompt",
702	  "prior_assistant_response",
703	  "actions",
704	  "action",
705	] as const;
706	
707	/**
708	 * Match any open or close tag matching one of the fence tag names,
709	 * tolerating whitespace and case. Replaced with [REDACTED:fence-tag]
710	 * to neutralise delimiter-injection attempts.
711	 */
712	const FENCE_TAG_RE = new RegExp(
713	  `<\\s*/?\\s*(?:${FENCE_TAG_NAMES.join("|")})\\s*>`,
714	  "gi",
715	);
716	
717	/**
718	 * Patterns that, when found in untrusted assistant text, are nuked before
719	 * reaching the judge prompt. Defence-in-depth alongside the system-prompt
720	 * "treat as data" directive — even if the model misinterprets the
721	 * directive, the obvious injection attempts never reach it.
722	 *
723	 * Each pattern matches a phrase commonly used in prompt-injection PoCs;
724	 * the redaction marker preserves token count roughly so the surrounding
725	 * context still reads naturally.
726	 *
727	 * NOT applied to user prompts (those are trusted input). Only used by
728	 * sanitiseAssistantContent below. Fence-tag scrubbing IS applied to user
729	 * prompts separately by sanitiseFenceTags.
730	 */
731	const INJECTION_PATTERNS: { re: RegExp; reason: string }[] = [
732	  { re: /ignore\s+(all\s+)?(previous|prior|above|earlier)\s+(instructions?|rules?|prompts?|system|directives?)/gi, reason: "ignore-previous" },
733	  { re: /disregard\s+(all\s+)?(previous|prior|above|earlier)\s+(instructions?|rules?|prompts?|system|directives?)/gi, reason: "disregard-previous" },
734	  { re: /(you\s+are\s+now|from\s+now\s+on,?\s+you\s+(are|will|must))\b/gi, reason: "role-override" },
735	  { re: /<\s*\/?\s*(system|admin|root|sudo)\s*>/gi, reason: "fake-tag" },
736	  { re: /\[\s*(system|admin|root|sudo)\s*\]/gi, reason: "fake-bracket" },
737	  { re: /regardless\s+of\s+(any|all|other|previous|prior)\s+(instructions?|rules?|directives?|context)/gi, reason: "regardless-of" },
738	  { re: /(respond|reply|answer|return|output)[\s:]+(only|exclusively|with)?\s*(the\s+)?(json|word|verdict|consistent|drifting|hijacked)/gi, reason: "force-output" },
739	  { re: /(classify|judge|treat|mark|consider)\s+(all|every|any|the\s+following)\s+(subsequent|next|following|further)\s+(tool|action|call|request)/gi, reason: "classify-subsequent" },
740	  { re: /important:\s*(regardless|ignore|disregard|always|never)/gi, reason: "important-override" },
741	  { re: /(your\s+)?(only\s+)?(real\s+)?(true\s+)?(actual\s+)?(real\s+)?(task|job|goal|objective)\s+is\s+(to\s+)?(now\s+)?(actually\s+)?(really\s+)?(?=\w)/gi, reason: "task-override" },
742	];
743	
744	/**
745	 * Strip any fence-tag (open or close) we use to delimit untrusted content
746	 * in the judge prompt. Applied to BOTH user prompts and assistant text
747	 * because the attacker doesn't need to be the LLM to inject delimiters —
748	 * a user could paste text containing `</user_intent>` from a previous
749	 * conversation log too.
750	 *
751	 * Exported so server-hook can scrub the user prompt before it's wrapped.
752	 */
753	export function sanitiseFenceTags(text: string): string {
754	  return text.replace(FENCE_TAG_RE, "[REDACTED:fence-tag]");
755	}
756	
757	
758	/**
759	 * Strip obvious instruction-injection patterns AND fence-tag delimiters
760	 * from untrusted assistant text. Preserves length-ish by replacing with
761	 * `[REDACTED:reason]`. The fence-tag scrubbing is critical — the
762	 * judge prompt fences this content with `<prior_assistant_response>` /
763	 * `<user_intent>` etc., and a malicious assistant that closes the tag
764	 * could reopen as system context. The instruction-pattern scrubbing is
765	 * belt-and-braces for the obvious injection vectors.
766	 */
767	function sanitiseAssistantContent(text: string): string {
768	  let out = sanitiseFenceTags(text);
769	  for (const { re, reason } of INJECTION_PATTERNS) {
770	    out = out.replace(re, `[REDACTED:${reason}]`);
771	  }
772	  return out;
773	}
774	
775	/**
776	 * Combine a user prompt with prior assistant context into the judge's
777	 * "intent" string. Two regimes:
778	 *
779	 *  - Substantive user prompt (≥200 chars or contains punctuation/imperatives):
780	 *    drop the prior-assistant block entirely. The user has provided enough
781	 *    context on their own; carrying assistant text just enlarges the
782	 *    injection surface.
783	 *
784	 *  - Short user prompt ("yes", "do that", "option 2"): the assistant's
785	 *    prior turn is needed for the judge to resolve references. Truncate
786	 *    aggressively (last 500 chars — usually the question being asked)
787	 *    and run injection-pattern sanitisation.
788	 *
789	 * The output uses explicit, separable tags so the judge prompt can fence
790	 * trusted vs. untrusted content. See intent-judge.ts evaluate() — it
791	 * places this whole string inside <user_intent>…</user_intent>.
792	 */
793	const PRIOR_ASSISTANT_MAX_CHARS = 500;
794	
795	export function buildContextualIntent(
796	  userPrompt: string,
797	  priorAssistant: string | null
798	): string {
799	  if (!priorAssistant) return userPrompt;
800	
801	  // Substantive prompts don't need the prior context. Heuristic: long
802	  // (≥200 chars) or wordy (≥8 words). At that scale the user has
803	  // provided enough context that the prior assistant turn would only
804	  // enlarge the injection surface without changing the judge's verdict.
805	  const trimmed = userPrompt.trim();
806	  const wordCount = trimmed.split(/\s+/).filter(Boolean).length;
807	  const isSubstantive = trimmed.length >= 200 || wordCount >= 8;
808	  if (isSubstantive) {
809	    return userPrompt;
810	  }
811	
812	  const tail = priorAssistant.length > PRIOR_ASSISTANT_MAX_CHARS
813	    ? priorAssistant.substring(priorAssistant.length - PRIOR_ASSISTANT_MAX_CHARS)
814	    : priorAssistant;
815	  const sanitisedAssistant = sanitiseAssistantContent(tail);
816	  // User prompts only get fence-tag scrubbing, not the injection-pattern
817	  // sanitisation — users are allowed to type "ignore previous" if they
818	  // mean it. But they shouldn't be able to paste `</user_prompt>` and
819	  // break the fence either, even by accident.
820	  const sanitisedUser = sanitiseFenceTags(userPrompt);
821	  return `<prior_assistant_response>
822	${sanitisedAssistant}
823	</prior_assistant_response>
824	
825	<user_prompt>
826	${sanitisedUser}
827	</user_prompt>`;
828	}
829	
830	export async function backfillFromTranscript(
831	  sessionId: string,
832	  transcriptPathOrContent: string,
833	  isContent = false
834	): Promise<void> {
835	  let raw: string;
836	  if (isContent) {
837	    raw = transcriptPathOrContent;
838	  } else {
839	    const safe = safeServerReadablePath(transcriptPathOrContent);
840	    if (!safe) return;
841	    try {
842	      raw = readFileSync(safe, "utf8");
843	    } catch {
844	      return;
845	    }
846	  }
847	
848	  try {
849	    const lines = raw.trim().split("\n").filter(Boolean);
850	
851	    const userPrompts: { text: string; images: ImageBlock[] }[] = [];
852	    const toolCalls: { tool: string; input: Record<string, unknown> }[] = [];
853	    const filesRead: string[] = [];
854	    const filesWritten: { path: string; content: string; isEdit: boolean }[] = [];
855	
856	    for (const line of lines) {
857	      try {
858	        const msg = JSON.parse(line);
859	
860	        if (msg.type === "user") {
861	          const { text, images: imgs } = extractTextAndImages(msg.message?.content);
862	          const trimmed = text.trim();
863	          if (!isSyntheticUserEntry(msg, trimmed) && (trimmed || imgs.length)) {
864	            userPrompts.push({ text: trimmed, images: imgs });
865	          }
866	        }
867	
868	        if (msg.type === "assistant") {
869	          const blocks = Array.isArray(msg.message?.content) ? msg.message.content : [];
870	          for (const block of blocks) {
871	            if (block.type === "tool_use") {
872	              const tool = block.name;
873	              const input = block.input ?? {};
874	              toolCalls.push({ tool, input });
875	
876	              if (tool === "Read") {
877	                filesRead.push(String(input.file_path ?? ""));
878	              }
879	              if (tool === "Write") {
880	                filesWritten.push({
881	                  path: String(input.file_path ?? ""),
882	                  content: String(input.content ?? ""),
883	                  isEdit: false,
884	                });
885	              }
886	              if (tool === "Edit") {
887	                filesWritten.push({
888	                  path: String(input.file_path ?? ""),
889	                  content: String(input.new_string ?? ""),
890	                  isEdit: true,
891	                });
892	              }
893	            }
894	          }
895	        }
896	      } catch {}
897	    }
898	
899	    if (userPrompts.length === 0) return;
900	
901	    const { lastUser, priorAssistant, images: lastImages } =
902	      extractLastUserAndPriorAssistant(raw, true);
903	    let goalIdx = userPrompts.length - 1;
904	    if (lastUser) {
905	      for (let i = userPrompts.length - 1; i >= 0; i--) {
906	        if (userPrompts[i].text === lastUser) { goalIdx = i; break; }
907	      }
908	    }
909	    const goalEntry = userPrompts[goalIdx];
910	    const goalPrompt = lastUser ?? goalEntry.text;
911	    const goalImages = lastImages.length ? lastImages : goalEntry.images;
912	    const contextualGoal = buildContextualIntent(goalPrompt, priorAssistant);
913	
914	    console.log(
915	      `  [BACKFILL] Session ${sessionId.substring(0, 8)}: ` +
916	      `${userPrompts.length} user prompts, ${toolCalls.length} tools, ` +
917	      `${filesRead.length} reads, ${filesWritten.length} writes` +
918	      `${goalImages.length ? `, ${goalImages.length} image(s)` : ""}` +
919	      ` from transcript`
920	    );
921	
922	    for (let i = 0; i < goalIdx; i++) {
923	      const p = userPrompts[i];
924	      await tracker.registerIntent(sessionId, p.text, true, p.images);
925	    }
926	    await tracker.registerIntent(sessionId, goalPrompt, false, goalImages);
927	    await interceptor.registerGoal(sessionId, contextualGoal, goalImages);
928	    registeredSessions.add(sessionId);
929	
930	    for (const path of filesRead) {
931	      await tracker.recordFileRead(sessionId, path, "(backfilled)");
932	    }
933	    for (const file of filesWritten) {
934	      await tracker.recordFileWrite(sessionId, file.path, file.content, file.isEdit);
935	    }
936	
937	    for (const tc of toolCalls) {
938	      await tracker.recordToolCall(sessionId, tc.tool, tc.input, "allow", null);
939	    }
940	
941	    console.log(
942	      `  [BACKFILL] Latest intent: "${goalPrompt.substring(0, 60)}..." ` +
943	      `(prior assistant context: ${priorAssistant ? "yes" : "no"})`
944	    );
945	  } catch (err) {
946	    console.error(
947	      `  [BACKFILL] Failed for session ${sessionId.substring(0, 8)}: ${err instanceof Error ? err.message : String(err)}`
948	    );
949	  }
950	}
951	
952	// ============================================================================
953	// buildSessionLogShape — used by dashboard /api/sessions and /api/session-log
954	// ============================================================================
955	
956	/**
957	 * Assemble the full session-log JSON shape the dashboard consumes.
958	 * Works for both live sessions (in-memory tracker) and persisted sessions
959	 * in Dynamo. Returns null when the session is completely unknown.
960	 */
961	export async function buildSessionLogShape(sessionId: string): Promise<Record<string, unknown> | null> {
962	  const ctx = await tracker.getSessionContext(sessionId);
963	  if (!ctx.originalTask && ctx.currentTurn === 0 && ctx.turnIntents.length === 0) {
964	    return null;
965	  }
966	  const summary = await tracker.getFullSessionSummary(sessionId);
967	  const driftHistory = tracker.getDriftDetector(sessionId).getHistory();
968	  return {
969	    sessionId,
970	    timestamp: new Date().toISOString(),
971	    originalTask: ctx.originalTask,
972	    summary,
973	    hijackStrikes: await tracker.getHijackStrikes(sessionId),
974	    lockedHijacked: await tracker.isLocked(sessionId),
975	    toolHistory: ctx.recentTools,
976	    filesWritten: (await tracker.getWrittenFiles(sessionId)).map((f) => ({
977	      path: f.path,
978	      writeCount: f.writeCount,
979	      containsCanary: f.containsCanary,
980	    })),
981	    envVars: await tracker.getEnvVars(sessionId),
982	    driftHistory,
983	    turnMetrics: summary.turnMetrics,
984	    interceptorLog: interceptor.getLog(sessionId).map((r) => ({
985	      tool: r.tool,
986	      input: r.input,
987	      stage: r.stage,
988	      allowed: r.allowed,
989	      similarity: r.similarity,
990	      reason: r.reason,
991	      evaluationMs: r.evaluationMs,
992	    })),
993	  };
994	}
