48	// CORS origin the dashboard container runs at. When unset, cross-origin
49	// requests are rejected — same-origin only, which is what the hook gets
50	// from Claude Code hooks.
51	const DASHBOARD_ORIGIN = process.env.DREDD_DASHBOARD_ORIGIN ?? "";
52	
53	/**
54	 * Apply CORS headers for endpoints the dashboard container calls. Returns
55	 * true and ends the response for OPTIONS preflight so the caller can bail.
56	 */
57	function applyCors(req: IncomingMessage, res: ServerResponse): boolean {
58	  if (!DASHBOARD_ORIGIN) return false;
59	  const origin = req.headers.origin;
60	  if (origin !== DASHBOARD_ORIGIN) return false;
61	  res.setHeader("Access-Control-Allow-Origin", DASHBOARD_ORIGIN);
62	  res.setHeader("Vary", "Origin");
63	  res.setHeader("Access-Control-Allow-Credentials", "true");
64	  res.setHeader("Access-Control-Allow-Methods", "GET, POST, OPTIONS");
65	  res.setHeader("Access-Control-Allow-Headers", "Content-Type, Authorization");
66	  if (req.method === "OPTIONS") {
67	    res.writeHead(204);
68	    res.end();
69	    return true;
70	  }
71	  return false;
72	}
