74	// =========================================================================
75	// POST /intent — UserPromptSubmit
76	// =========================================================================
77	async function handleIntent(req: IncomingMessage, res: ServerResponse) {
78	  const identity = await authenticateHookRequest(req, res);
79	  if (!identity) return;
80	
81	  const body = JSON.parse(await readBody(req, BODY_LIMIT_TRANSCRIPT));
82	  const { session_id, prompt, transcript_path, cwd } = body;
83	  const transcriptContent: string | undefined = body.transcript_content;
84	  const claudeMdContent: string | undefined = body.claudemd_content;
85	
86	  if (rejectInvalidSessionId(res, session_id)) return;
87	  if (!prompt) {
88	    return json(res, 400, { error: "Missing prompt" });
89	  }
90	
91	  // Stamp the session owner from the validated API key so the dashboard
92	  // can scope sessions to the signed-in Clerk user. First writer wins;
93	  // calling more than once with the same key is idempotent.
94	  if (identity.keyValid && identity.ownerSub) {
95	    await tracker.setSessionOwner(session_id, identity.ownerSub, identity.ownerEmail);
96	  }
97	
98	  if (cwd) {
99	    await tracker.setProjectRoot(session_id, cwd);
100	
101	    if (!registeredSessions.has(session_id)) {
102	      let scan: ClaudeMdScanResult | null = null;
103	      if (claudeMdContent) {
104	        scan = scanClaudeMdContent(claudeMdContent, `${cwd}/CLAUDE.md`);
105	      } else {
