126	    }
127	  }
128	
129	  const mode: TrustMode = body.mode ?? CONFIG.mode;
130	
131	  const { priorAssistant, images: transcriptImages } = transcriptContent
132	    ? extractLastUserAndPriorAssistant(transcriptContent, true)
133	    : transcript_path
