135	      : { priorAssistant: null, images: [] as ImageBlock[] };
136	
137	  const result = await tracker.registerIntent(session_id, prompt, mode === "interactive", transcriptImages);
138	
139	  const contextualGoal = buildContextualIntent(prompt, priorAssistant);
140	
141	  if (transcriptImages.length) {
