143	      `  [${session_id.substring(0, 8)}] [INTENT] ${transcriptImages.length} image(s) attached to intent`
144	    );
145	  }
146	
147	  if (result.isOriginal && !registeredSessions.has(session_id)) {
148	    await interceptor.registerGoal(session_id, contextualGoal, transcriptImages);
149	    registeredSessions.add(session_id);
150	  }
