152	  if ((mode === "interactive" || mode === "learn") && !result.isOriginal) {
153	    // Treat short replies as confirmations of the previous turn rather than
154	    // standalone goals. Includes "option N" / "option foo" so users picking
155	    // from a clarifying question don't reset the goal to a meaningless
156	    // 2-word string. Stays in sync with isConfirmationPrompt() in
157	    // server-core.ts (used by transcript backfill) — divergence here was
158	    // the cause of "option 2" being treated as a new goal and tripping
159	    // drift-deny on the next tool call.
160	    const confirmationOnly =
161	      /^\s*(yes|yeah|yep|ok|okay|sure|do it|go ahead|go|proceed|continue|y|k|confirm|approved?|lgtm|ship it|sounds good|that's right|correct|exactly|please|thanks|thank you|option\s+\w+|👍)\s*[.!?👍]*\s*$/i;
