166	        `  [${session_id.substring(0, 8)}] [INTENT] ${mode} mode: "${prompt.trim()}" is a confirmation — keeping previous goal`
167	      );
168	    } else {
169	      await interceptor.registerGoal(session_id, contextualGoal, transcriptImages);
170	      console.log(
171	        `  [${session_id.substring(0, 8)}] [INTENT] ${mode} mode: updated goal to "${prompt.substring(0, 60)}..." ` +
172	        `(prior assistant context: ${priorAssistant ? "yes" : "no"}, ` +
173	        `drift from original: ${result.driftFromOriginal?.toFixed(3) ?? "n/a"})`
174	      );
175	    }
176	  }
177	
178	  const classification = tracker.classifyDrift(result.driftFromOriginal);
179	  const reminder = mode === "autonomous"
180	    ? await tracker.getGoalReminder(session_id, result.driftFromOriginal)
181	    : null;
182	
183	  const hookResponse: Record<string, unknown> = {};
184	  if (reminder) {
