186	  }
187	
188	  addFeed({
189	    timestamp: new Date().toISOString(),
190	    type: "intent",
191	    prompt: prompt.substring(0, 500),
192	    sessionId: session_id,
193	    reason: `Turn ${result.turnNumber}: ${classification}${result.driftFromOriginal !== null ? ` (drift: ${result.driftFromOriginal.toFixed(3)})` : ""}`,
194	    ownerSub: identity.ownerSub,
