415	        || (await tracker.getSessionContext(session_id)).originalTask
416	        || "unknown";
417	      const userVisibleGoal = currentGoal.includes("USER PROMPT:\n")
418	        ? currentGoal.split("USER PROMPT:\n").pop()!.trim()
419	        : currentGoal;
