426	        `[SECURITY] Tool call ${tool_name} was blocked. Reason: ${result.reason}. ` +
427	        `Stay focused on the current task: "${userVisibleGoal}".`;
428	    }
429	  } else {
430	    hookResponse.hookSpecificOutput = {
431	      hookEventName: "PreToolUse",
432	      permissionDecision: "allow",
433	      permissionDecisionReason: `Judge AI Dredd: ${result.reason}`,
434	    };
435	  }
436	
437	  if (isBenchmarkFormat) {
438	    const verdict = result.judgeVerdict?.verdict
439	      ?? (result.allowed ? "consistent" : "hijacked");
440	    const confidence = result.judgeVerdict?.confidence ?? (result.allowed ? 0.95 : 0.90);
441	    const rationale = result.judgeVerdict?.reasoning ?? result.reason;
442	    return json(res, 200, { verdict, confidence, rationale });
443	  }
444	
445	  json(res, 200, {
446	    ...hookResponse,
447	    _meta: {
448	      allowed: result.allowed,
449	      stage: lockState?.justLocked ? "session-locked" : result.stage,
450	      similarity: result.similarity,
451	      reason: lockState?.justLocked ? LOCKED_MESSAGE : result.reason,
452	      evaluationMs: result.evaluationMs,
453	      judgeVerdict: result.judgeVerdict
454	        ? {
455	            verdict: result.judgeVerdict.verdict,
456	            confidence: result.judgeVerdict.confidence,
457	            reasoning: result.judgeVerdict.reasoning,
458	          }
459	        : null,
460	      hijackStrikes: lockState?.strikes ?? (await tracker.getHijackStrikes(session_id)),
461	      locked: lockState?.locked ?? (await tracker.isLocked(session_id)),
462	    },
463	  });
464	}
465	
466	// =========================================================================
467	// POST /track — PostToolUse
468	// =========================================================================
469	async function handleTrack(req: IncomingMessage, res: ServerResponse) {
470	  const identity = await authenticateHookRequest(req, res);
471	  if (!identity) return;
472	
473	  const body = JSON.parse(await readBody(req));
474	  const { session_id, tool_name, tool_input, tool_output } = body;
475	
476	  if (rejectInvalidSessionId(res, session_id)) return;
477	  if (!tool_name) {
478	    return json(res, 400, { error: "Missing tool_name" });
479	  }
480	
481	  if (tool_name === "Read") {
482	    await tracker.recordFileRead(
483	      session_id,
484	      String(tool_input?.file_path ?? ""),
485	      String(tool_output ?? "")
486	    );
487	  }
488	
489	  if (tool_name === "Write") {
490	    await tracker.recordFileWrite(
491	      session_id,
492	      String(tool_input?.file_path ?? ""),
493	      String(tool_input?.content ?? ""),
494	      false
495	    );
496	  }
497	
498	  if (tool_name === "Edit") {
499	    await tracker.recordFileWrite(
500	      session_id,
501	      String(tool_input?.file_path ?? ""),
502	      String(tool_input?.new_string ?? ""),
503	      true
504	    );
505	  }
506	
507	  if (tool_name === "Bash") {
508	    await tracker.recordEnvVar(session_id, String(tool_input?.command ?? ""));
509	  }
510	
511	  json(res, 200, {});
512	}
513	
514	// =========================================================================
515	// POST /end — Stop
516	// =========================================================================
517	async function handleEnd(req: IncomingMessage, res: ServerResponse) {
518	  const identity = await authenticateHookRequest(req, res);
519	  if (!identity) return;
520	
521	  const body = JSON.parse(await readBody(req));
522	  const { session_id } = body;
523	
524	  if (rejectInvalidSessionId(res, session_id)) return;
525	
526	  const sessionLog = await buildSessionLogShape(session_id);
527	  const summary = (sessionLog?.summary as any) ?? { turns: 0, toolCalls: 0, denied: 0 };
528	
529	  console.log(
530	    `[END] Session ${session_id.substring(0, 8)}: ` +
531	    `${summary.turns} turns, ${summary.toolCalls} tools, ` +
532	    `${summary.denied} denied`
533	  );
534	
535	  registeredSessions.delete(session_id);
536	  await tracker.endSession(session_id);
537	  interceptor.reset(session_id);
538	
539	  json(res, 200, { summary });
540	}
541	
542	// =========================================================================
543	// GET /session/:id — Debug
544	// =========================================================================
545	async function handleSessionGet(res: ServerResponse, sessionId: string) {
546	  if (rejectInvalidSessionId(res, sessionId)) return;
547	  const ctx = await tracker.getSessionContext(sessionId);
548	  const summary = await tracker.getFullSessionSummary(sessionId);
549	  json(res, 200, { ...ctx, summary });
550	}
551	
552	// =========================================================================
553	// POST /pivot / /compact
554	// =========================================================================
555	async function handlePivot(req: IncomingMessage, res: ServerResponse) {
556	  const identity = await authenticateHookRequest(req, res);
557	  if (!identity) return;
558	
559	  const body = JSON.parse(await readBody(req));
560	  const { session_id, reason } = body;
561	
562	  if (rejectInvalidSessionId(res, session_id)) return;
563	
564	  await tracker.pivotSession(session_id, reason ?? "User changed direction");
565	
566	  interceptor.reset(session_id);
567	  registeredSessions.delete(session_id);
568	
569	  json(res, 200, { pivoted: true, reason: reason ?? "User changed direction" });
570	}
571	
572	async function handleCompact(req: IncomingMessage, res: ServerResponse) {
573	  const identity = await authenticateHookRequest(req, res);
574	  if (!identity) return;
575	
576	  const body = JSON.parse(await readBody(req));
577	  const { session_id } = body;
578	
579	  if (rejectInvalidSessionId(res, session_id)) return;
580	
581	  console.log(
582	    `  [COMPACT] Session ${session_id.substring(0, 8)}: context compaction detected`
583	  );
584	
585	  await tracker.recordTurnMetrics(
586	    session_id,
587	    null,
588	    null,
589	    0,
590	    0,
591	    false,
592	    false
593	  );
594	
595	  json(res, 200, { noted: true });
596	}
597	
598	// =========================================================================
599	// Router
600	// =========================================================================
601	const server = createServer(async (req, res) => {
602	  const url = new URL(req.url ?? "/", `http://localhost:${PORT}`);
603	
604	  try {
605	    // GET / — tiny status landing page. The hook container has no
606	    // dashboard UI (that lives on the dashboard container). This page
607	    // is for operators / users who hit the URL directly to confirm
608	    // which container is on the other end and link them onward.
609	    if (req.method === "GET" && url.pathname === "/") {
610	      const pkg = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8"));
611	      const dashboardOrigin = process.env.DREDD_DASHBOARD_ORIGIN ?? "";
612	      const html = `<!DOCTYPE html>
613	<html lang="en">
614	<head>
615	<meta charset="UTF-8">
616	<meta name="viewport" content="width=device-width,initial-scale=1.0">
617	<title>Judge AI Dredd — Hook API</title>
618	<style>
619	  body { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; background: #0d1117; color: #c9d1d9; margin: 0; padding: 40px 24px; }
620	  .card { max-width: 720px; margin: 0 auto; background: #161b22; border: 1px solid #30363d; border-radius: 8px; padding: 28px; }
621	  h1 { font-size: 20px; margin: 0 0 4px; color: #f0f6fc; }
622	  h1 span { color: #58a6ff; }
623	  .sub { color: #8b949e; font-size: 13px; margin-bottom: 20px; }
624	  .grid { display: grid; grid-template-columns: 140px 1fr; gap: 8px 16px; font-size: 13px; margin: 20px 0; }
625	  .k { color: #8b949e; }
626	  .v { color: #c9d1d9; word-break: break-all; }
627	  .v.green { color: #3fb950; }
628	  .v.amber { color: #d29922; }
629	  .pill { display: inline-block; padding: 2px 8px; border-radius: 12px; font-size: 11px; background: #1f6feb33; color: #58a6ff; border: 1px solid #1f6feb; }
630	  ul { list-style: none; padding: 0; margin: 16px 0; }
631	  li { padding: 4px 0; }
632	  li code { color: #d29922; }
633	  a { color: #58a6ff; }
634	  .muted { color: #8b949e; font-size: 12px; margin-top: 24px; line-height: 1.6; }
635	</style>
636	</head>
637	<body>
638	<div class="card">
639	  <h1>Judge AI <span>Dredd</span> — Hook API</h1>
640	  <div class="sub">PreToolUse defence service for Claude Code hooks. <span class="pill">role: hook</span></div>
641	
642	  <div class="grid">
643	    <div class="k">Version</div><div class="v">${pkg.version}</div>
644	    <div class="k">Status</div><div class="v green">ok</div>
645	    <div class="k">Mode</div><div class="v">${CONFIG.mode}</div>
646	    <div class="k">Backend</div><div class="v">${CONFIG.judgeBackend}</div>
647	    <div class="k">Judge model</div><div class="v">${CONFIG.judgeModel}</div>
648	    <div class="k">Embedding</div><div class="v">${CONFIG.embeddingModel}</div>
649	    <div class="k">Prompt variant</div><div class="v">${CONFIG.hardened || "standard"}</div>
650	    <div class="k">Active sessions</div><div class="v">${registeredSessions.size}</div>
651	    <div class="k">Auth mode</div><div class="v ${process.env.DREDD_AUTH_MODE === "required" ? "green" : "amber"}">${process.env.DREDD_AUTH_MODE ?? "optional"}</div>
652	  </div>
653	
654	  <div style="font-size: 12px; color: #8b949e; margin: 16px 0 8px; text-transform: uppercase; letter-spacing: 0.5px;">Hook endpoints</div>
655	  <ul>
656	    <li><code>POST /intent</code> — UserPromptSubmit</li>
657	    <li><code>POST /evaluate</code> — PreToolUse (judge pipeline)</li>
658	    <li><code>POST /track</code> — PostToolUse</li>
659	    <li><code>POST /end</code> · <code>/pivot</code> · <code>/compact</code></li>
660	    <li><code>GET /api/health</code> · <code>/api/whoami</code> · <code>/api/data-status</code></li>
661	    <li><code>GET /api/feed</code> · <code>POST /api/mode</code> <span style="color:#8b949e">(cross-origin from dashboard)</span></li>
662	  </ul>
663	
664	  <div class="muted">
665	    The full operator dashboard lives on a separate container.
666	    ${dashboardOrigin ? `<br>Dashboard: <a href="${dashboardOrigin}">${dashboardOrigin}</a>` : `<br>Dashboard origin not configured (DREDD_DASHBOARD_ORIGIN unset).`}
667	    <br>To install the hook in your project, run <code>curl -O ${"https://" + (req.headers["x-forwarded-host"] || req.headers.host || "localhost")}/api/integration-bundle</code> from the dashboard.
668	  </div>
669	</div>
670	</body>
671	</html>`;
672	      res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
673	      res.end(html);
674	      return;
675	    }
676	
677	    // /health (ALB target-group health check) — never CORSed, never auth'd.
678	    if (req.method === "GET" && url.pathname === "/health") {
679	      const pkg = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8"));
680	      return json(res, 200, {
681	        status: "ok",
682	        version: pkg.version,
683	        role: "hook",
684	        config: CONFIG,
685	        activeSessions: registeredSessions.size,
686	      });
687	    }
688	
689	    // /api/health — same payload, but the dashboard browser polls this
690	    // cross-origin to render the version + mode badge in its top bar.
691	    // Apply CORS (and respond to OPTIONS preflight) so it works.
692	    if (url.pathname === "/api/health") {
693	      if (applyCors(req, res)) return;
694	      if (req.method !== "GET") return json(res, 405, { error: "Method not allowed" });
695	      const pkg = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8"));
696	      return json(res, 200, {
697	        status: "ok",
698	        version: pkg.version,
699	        role: "hook",
700	        config: CONFIG,
701	        activeSessions: registeredSessions.size,
702	      });
703	    }
704	
705	    // /api/whoami — OIDC discovery. No auth; read-only.
706	    if (req.method === "GET" && url.pathname === "/api/whoami") {
707	      const oidcData = req.headers["x-amzn-oidc-data"] as string | undefined;
708	      const oidcIdentity = req.headers["x-amzn-oidc-identity"] as string | undefined;
709	      const hasAccessToken = !!req.headers["x-amzn-oidc-accesstoken"];
710	
711	      let claims: Record<string, unknown> | null = null;
712	      let decodeError: string | null = null;
713	      if (oidcData) {
714	        try {
715	          const parts = oidcData.split(".");
716	          if (parts.length === 3) {
717	            const payload = Buffer.from(parts[1], "base64").toString("utf8");
718	            claims = JSON.parse(payload);
719	          } else {
720	            decodeError = `Expected 3 JWT segments, got ${parts.length}`;
721	          }
722	        } catch (err) {
723	          decodeError = err instanceof Error ? err.message : String(err);
724	        }
725	      }
726	
727	      return json(res, 200, {
728	        role: "hook",
729	        authWired: !!oidcData,
730	        identity: oidcIdentity ?? null,
731	        hasAccessToken,
732	        claims,
733	        decodeError,
734	        seenHeaders: Object.keys(req.headers)
735	          .filter((h) => h.toLowerCase().startsWith("x-amzn-"))
736	          .sort(),
737	      });
738	    }
739	
740	    // /api/data-status — EFS mount probe. Used by the dashboard container
741	    // to show operators whether /data survives restart. Read-only.
742	    if (req.method === "GET" && url.pathname === "/api/data-status") {
743	      const sessionDir = CONFIG.logDir;
744	      const consoleDir = CONFIG.consoleLogDir;
745	      const dataDir =
746	        sessionDir.endsWith("/sessions") ? sessionDir.slice(0, -"/sessions".length) : sessionDir;
747	
748	      let mounts: Array<{ source: string; target: string; fstype: string; options: string }> = [];
749	      try {
750	        mounts = readFileSync("/proc/mounts", "utf8")
751	          .split("\n")
752	          .filter(Boolean)
753	          .map((line) => {
754	            const [source, target, fstype, options] = line.split(/\s+/);
755	            return { source, target, fstype, options };
756	          });
757	      } catch {
758	        // Not Linux.
759	      }
760	
761	      const mountFor = (path: string) => {
762	        const match = mounts
763	          .filter((m) => path === m.target || path.startsWith(m.target + "/"))
764	          .sort((a, b) => b.target.length - a.target.length)[0];
765	        return match ?? null;
766	      };
767	
768	      const describeDir = (dir: string) => {
769	        if (!existsSync(dir)) {
770	          return { path: dir, exists: false };
771	        }
772	        let files: string[] = [];
773	        try { files = readdirSync(dir); } catch { files = []; }
774	        let bytes = 0;
775	        let newest: { name: string; mtime: string; size: number } | null = null;
776	        for (const name of files) {
777	          try {
778	            const st = statSync(join(dir, name));
779	            if (!st.isFile()) continue;
780	            bytes += st.size;
781	            if (!newest || st.mtimeMs > Date.parse(newest.mtime)) {
782	              newest = { name, mtime: new Date(st.mtimeMs).toISOString(), size: st.size };
783	            }
784	          } catch {}
785	        }
786	        return { path: dir, exists: true, fileCount: files.length, totalBytes: bytes, newest };
787	      };
788	
789	      const dataMount = mountFor(dataDir);
790	      return json(res, 200, {
791	        dataDir,
792	        sessionDir,
793	        consoleDir,
794	        mount: dataMount
795	          ? {
796	              source: dataMount.source,
797	              target: dataMount.target,
798	              fstype: dataMount.fstype,
799	              options: dataMount.options,
800	              persistent:
801	                dataMount.fstype === "nfs" ||
802	                dataMount.fstype === "nfs4" ||
803	                dataMount.fstype === "efs" ||
804	                !["overlay", "overlay2", "tmpfs", "aufs"].includes(dataMount.fstype),
805	            }
806	          : { persistent: false, note: "not a mount point — ephemeral container layer" },
807	        sessions: describeDir(sessionDir),
808	        logs: describeDir(consoleDir),
809	      });
810	    }
811	
812	    // /api/feed — cross-origin from the dashboard.
813	    if (url.pathname === "/api/feed") {
814	      if (applyCors(req, res)) return;
815	      if (req.method === "GET") return json(res, 200, feed);
816	    }
817	
818	    // /api/mode — cross-origin from the dashboard. Flips trust mode for
819	    // the whole server in-process. Preflight handled above; POST below.
820	    if (url.pathname === "/api/mode") {
821	      if (applyCors(req, res)) return;
822	      if (req.method === "POST") {
823	        const body = JSON.parse(await readBody(req));
824	        const next = body.mode;
825	        if (next !== "interactive" && next !== "autonomous" && next !== "learn") {
826	          return json(res, 400, { error: "mode must be one of: interactive, autonomous, learn" });
827	        }
828	        const prev = CONFIG.mode;
829	        CONFIG.mode = next as TrustMode;
830	        console.log(`  [MODE] runtime switch: ${prev} → ${next}`);
831	        return json(res, 200, { mode: CONFIG.mode, previous: prev });
832	      }
833	    }
834	
835	    // Debug/test helper — exposes a session's live context by id. No auth;
836	    // returns only the in-memory slice. Keep simple — dashboard has
837	    // /api/session-log/:id for the full shape.
838	    if (req.method === "GET" && url.pathname.startsWith("/session/")) {
839	      const id = url.pathname.split("/session/")[1];
840	      return await handleSessionGet(res, id);
841	    }
842	
843	    // ------ Hook events -------------------------------------------------
844	    if (req.method === "POST" && url.pathname === "/intent")   return await handleIntent(req, res);
845	    if (req.method === "POST" && url.pathname === "/register") return await handleRegister(req, res);
846	    if (req.method === "POST" && url.pathname === "/evaluate") return await handleEvaluate(req, res);
847	    if (req.method === "POST" && url.pathname === "/track")    return await handleTrack(req, res);
848	    if (req.method === "POST" && url.pathname === "/end")      return await handleEnd(req, res);
849	    if (req.method === "POST" && url.pathname === "/pivot")    return await handlePivot(req, res);
850	    if (req.method === "POST" && url.pathname === "/compact")  return await handleCompact(req, res);
851	
852	    json(res, 404, { error: "Not found" });
853	  } catch (err) {
854	    if (err instanceof BodyTooLargeError) {
855	      console.warn(`[413] ${req.method} ${url.pathname}: body exceeded ${err.bodyLimit} bytes`);
856	      return json(res, 413, { error: "Request body too large" });
857	    }
858	    if (err instanceof SyntaxError) {
859	      console.warn(`[400] ${req.method} ${url.pathname}: invalid JSON: ${err.message}`);
860	      return json(res, 400, { error: "Invalid JSON body" });
861	    }
862	    console.error(`[ERROR] ${req.method} ${url.pathname}:`, err);
863	    json(res, 500, { error: "Internal server error" });
864	  }
865	});
866	
867	server.headersTimeout = 30_000;
868	server.requestTimeout = 120_000;
869	server.keepAliveTimeout = 5_000;
870	
871	// =========================================================================
872	// Startup
873	// =========================================================================
874	export async function main() {
875	  const pkg = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8"));
876	
877	  console.log("█".repeat(50));
878	  console.log(`  JUDGE AI DREDD — HOOK Server v${pkg.version}`);
879	  console.log("█".repeat(50));
880	
881	  if (process.env.DREDD_SKIP_PREFLIGHT === "1") {
882	    console.warn("  [PREFLIGHT] skipped (DREDD_SKIP_PREFLIGHT=1) — test mode");
883	  } else {
884	    await interceptor.preflight();
885	  }
886	  console.log(`  Mode:            ${CONFIG.mode}`);
887	  console.log(`  Embedding model: ${CONFIG.embeddingModel}`);
888	  console.log(`  Judge backend:   ${CONFIG.judgeBackend}`);
889	  console.log(`  Judge model:     ${CONFIG.judgeModel}`);
890	  console.log(`  Judge prompt:    ${CONFIG.hardened || "standard"}`);
891	  if (CONFIG.judgeEffort) console.log(`  Judge effort:    ${CONFIG.judgeEffort}`);
892	  console.log(`  Thresholds:      review=${CONFIG.reviewThreshold}, deny=${CONFIG.denyThreshold}`);
893	  console.log(`  Hijack lock:     ${CONFIG.hijackThreshold} strike${CONFIG.hijackThreshold === 1 ? "" : "s"} (autonomous mode only)`);
894	  console.log(`  Session logs:    ${CONFIG.logDir}`);
895	  console.log(`  Console logs:    ${CONFIG.consoleLogDir}`);
896	  console.log(`  Dashboard CORS:  ${DASHBOARD_ORIGIN || "(disabled — DREDD_DASHBOARD_ORIGIN unset)"}`);
897	
898	  server.listen(PORT, "0.0.0.0", () => {
899	    console.log(`\n  Listening on http://0.0.0.0:${PORT}`);
900	    console.log(`\n  Endpoints:`);
901	    console.log(`    POST /intent    — UserPromptSubmit (register intent)`);
902	    console.log(`    POST /evaluate  — PreToolUse (evaluate tool call)`);
903	    console.log(`    POST /track     — PostToolUse (record file/env state)`);
904	    console.log(`    POST /end       — Stop (write log, cleanup)`);
905	    console.log(`    POST /pivot     — explicit direction change`);
906	    console.log(`    POST /compact   — context compaction notification`);
907	    console.log(`    POST /api/mode  — runtime trust-mode switch`);
908	    console.log(`    GET  /health    — health check + version`);
909	    console.log(`    GET  /api/feed  — live event ring buffer (cross-origin)`);
910	    console.log("█".repeat(50));
911	  });
912	
913	  process.on("SIGTERM", () => {
914	    console.log("SIGTERM received, shutting down gracefully");
915	    server.close(async () => {
916	      // Drain pending log lines to disk before exiting so the last
917	      // few seconds of activity (the SIGTERM, the close events) make
918	      // it into the daily file.
919	      await flushLogs();
920	      process.exit(0);
921	    });
922	    setTimeout(() => process.exit(1), 10_000);
923	  });
924	}
